-- Local preparation only; never executed against production by development tests.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('newave_flow_schema'));
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM schema_migrations WHERE version='V021__praise_team') THEN RAISE EXCEPTION 'V021 already applied'; END IF;
 IF NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version='V020__officer_organization') THEN RAISE EXCEPTION 'V020 required'; END IF;
END $$;
CREATE TABLE praise_terms(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,term_year integer NOT NULL CHECK(term_year BETWEEN 2000 AND 2100),half integer NOT NULL CHECK(half IN(1,2)),revision bigint NOT NULL DEFAULT 0,UNIQUE(term_year,half));
CREATE TABLE praise_members(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,term_id bigint NOT NULL REFERENCES praise_terms(id),user_id bigint REFERENCES users(id) ON DELETE SET NULL,student_id bigint REFERENCES students(id) ON DELETE SET NULL,parts text NOT NULL DEFAULT '[]',active boolean NOT NULL DEFAULT true,UNIQUE(term_id,user_id),UNIQUE(term_id,student_id),CHECK(user_id IS NULL OR student_id IS NULL));
CREATE INDEX ix_praise_members_user ON praise_members(user_id,active);
CREATE TABLE praise_weeks(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,term_id bigint NOT NULL REFERENCES praise_terms(id),worship_date date NOT NULL,practice_date date NOT NULL,start_time time NOT NULL,end_time time NOT NULL,schedule_version bigint NOT NULL DEFAULT 0,slots text NOT NULL DEFAULT '{}',published_slots text,published_at timestamp,updated_at timestamp,UNIQUE(term_id,worship_date),CHECK(end_time>start_time));
CREATE TABLE praise_responses(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,term_id bigint NOT NULL REFERENCES praise_terms(id),user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,response_month varchar(7) NOT NULL,dates text NOT NULL DEFAULT '[]',schedule_versions text NOT NULL DEFAULT '{}',submitted_at timestamp NOT NULL,UNIQUE(term_id,user_id,response_month));
CREATE TABLE praise_prayers(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,term_id bigint NOT NULL REFERENCES praise_terms(id),meeting_date date NOT NULL,host_id bigint REFERENCES praise_members(id),zoom_url varchar(1000) DEFAULT '',UNIQUE(term_id,meeting_date));
CREATE TABLE praise_pdfs(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,week_id bigint NOT NULL REFERENCES praise_weeks(id),file_version integer NOT NULL,content bytea NOT NULL,page_count integer NOT NULL CHECK(page_count BETWEEN 1 AND 200),uploaded_by_id bigint REFERENCES users(id) ON DELETE SET NULL,uploaded_at timestamp NOT NULL,UNIQUE(week_id,file_version));
INSERT INTO schema_migrations(version) VALUES('V021__praise_team');
COMMIT;
